(()=>{document.addEventListener('click',event=>{const button=event.target.closest?.('#openStoryBtn,#mobileTreeStory');if(!button||typeof selected==='undefined'||selected!=='edward_milo_jr')return;const index=typeof BRANCH_TOURS!=='undefined'?BRANCH_TOURS.webb?.steps?.findIndex(s=>s.id==='edward_milo_jr'):-1;if(index<0||!window.AncestryTour?.begin)return;event.preventDefault();event.stopImmediatePropagation();window.AncestryTour.begin('webb',index);},true);})();
